function GrainSamplerProbeMaker.init() GrainSamplerProbeMaker.ironStock=18; GrainSamplerProbeMaker.bronzeStock=14; GrainSamplerProbeMaker.woodStock=10; GrainSamplerProbeMaker.leatherStock=8; GrainSamplerProbeMaker.silverStock=8; GrainSamplerProbeMaker.goldStock=6; GrainSamplerProbeMaker.jewelStock=4; GrainSamplerProbeMaker.pearlStock=4; GrainSamplerProbeMaker.productStock={}; GrainSamplerProbeMaker.buildings={}; GrainSamplerProbeMaker.maker=nil; GrainSamplerProbeMaker.activeMaking={}; GrainSamplerProbeMaker.totalProducts=0; GrainSamplerProbeMaker.dayTimer=0; print("[GrainSamplerProbeMaker] Royal Grain Sampler Probe Maker System initialized (6 products, 4 buildings)") end
function GrainSamplerProbeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainSamplerProbeMaker.maker={name=n or ("Sondar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sondar najet: %s (spretnost: %d)",GrainSamplerProbeMaker.maker.name,s),"success") end; return true end
function GrainSamplerProbeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainSamplerProbeMaker.build(id) local ok,e=GrainSamplerProbeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainSamplerProbeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainSamplerProbeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainSamplerProbeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainSamplerProbeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainSamplerProbeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainSamplerProbeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainSamplerProbeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainSamplerProbeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainSamplerProbeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainSamplerProbeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainSamplerProbeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainSamplerProbeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainSamplerProbeMaker.buildings==0 then return false,"Potrebna sondalna delavnica" end; if not GrainSamplerProbeMaker.maker then return false,"Potreben sondar" end; return true end
function GrainSamplerProbeMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainSamplerProbeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainSamplerProbeMaker.ironStock=GrainSamplerProbeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainSamplerProbeMaker.bronzeStock=GrainSamplerProbeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainSamplerProbeMaker.woodStock=GrainSamplerProbeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainSamplerProbeMaker.leatherStock=GrainSamplerProbeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainSamplerProbeMaker.silverStock=GrainSamplerProbeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainSamplerProbeMaker.goldStock=GrainSamplerProbeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainSamplerProbeMaker.jewelStock=GrainSamplerProbeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainSamplerProbeMaker.pearlStock=GrainSamplerProbeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainSamplerProbeMaker.maker then t=math.max(1,t-math.floor(GrainSamplerProbeMaker.maker.skill/13)) end; table.insert(GrainSamplerProbeMaker.activeMaking,{id="grainsamplerprobe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainSamplerProbeMaker.completeMaking(m) local q=1.0+(GrainSamplerProbeMaker.getQualityBonus()/100); if GrainSamplerProbeMaker.maker then q=q+(GrainSamplerProbeMaker.maker.skill/140) end; q=math.min(2.5,q); GrainSamplerProbeMaker.productStock[m.productType]=(GrainSamplerProbeMaker.productStock[m.productType] or 0)+m.quantity; GrainSamplerProbeMaker.totalProducts=GrainSamplerProbeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainSamplerProbeMaker.maker then GrainSamplerProbeMaker.maker.itemsMade=GrainSamplerProbeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainSamplerProbeMaker.maker.skill=math.min(100,GrainSamplerProbeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sonda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainsamplerprobe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainSamplerProbeMaker.update(dt) if not _G.state then return end; GrainSamplerProbeMaker.dayTimer=GrainSamplerProbeMaker.dayTimer+dt; if GrainSamplerProbeMaker.dayTimer>=30 then GrainSamplerProbeMaker.dayTimer=0; for i=#GrainSamplerProbeMaker.activeMaking,1,-1 do local m=GrainSamplerProbeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainSamplerProbeMaker.completeMaking(m); table.remove(GrainSamplerProbeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainSamplerProbeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainSamplerProbeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainSamplerProbeMaker.getStats() return {ironStock=GrainSamplerProbeMaker.ironStock,bronzeStock=GrainSamplerProbeMaker.bronzeStock,woodStock=GrainSamplerProbeMaker.woodStock,leatherStock=GrainSamplerProbeMaker.leatherStock,silverStock=GrainSamplerProbeMaker.silverStock,goldStock=GrainSamplerProbeMaker.goldStock,jewelStock=GrainSamplerProbeMaker.jewelStock,pearlStock=GrainSamplerProbeMaker.pearlStock,productStock=GrainSamplerProbeMaker.productStock,numBuildings=#GrainSamplerProbeMaker.buildings,hasMaker=GrainSamplerProbeMaker.maker~=nil,makerName=GrainSamplerProbeMaker.maker and GrainSamplerProbeMaker.maker.name or "—",makerSkill=GrainSamplerProbeMaker.maker and GrainSamplerProbeMaker.maker.skill or 0,activeMaking=#GrainSamplerProbeMaker.activeMaking,totalProducts=GrainSamplerProbeMaker.totalProducts} end
